package com.bank.hierarchy.service;

import com.bank.hierarchy.model.DeskNode;
import java.util.logging.Logger;

// Computes the longest escalation chain (diameter in nodes) in one post-order pass.
public class TreeDiameterService {
    private static final Logger log = Logger.getLogger(TreeDiameterService.class.getName());

    private int maxDiameter;

    public int longestEscalationChain(DeskNode root) {
        maxDiameter = 0;
        height(root);
        log.info(() -> "Longest escalation chain (nodes) = " + maxDiameter);
        return maxDiameter;
    }

    // Returns the height of the subtree while updating the global diameter.
    private int height(DeskNode node) {
        if (node == null) {
            return 0;
        }
        int leftHeight = height(node.getLeft());
        int rightHeight = height(node.getRight());

        // Candidate diameter through this desk, counted in nodes.
        int through = leftHeight + rightHeight + 1;
        if (through > maxDiameter) {
            maxDiameter = through;
            log.fine(() -> "New longest chain through " + node.getName()
                    + " = " + through + " nodes");
        }
        // Height returned to parent: the deeper side plus this node.
        return Math.max(leftHeight, rightHeight) + 1;
    }
}
