    private static final Logger log = Logger.getLogger(DiameterApplication.class.getName());

    public static void main(String[] args) {
        // Longest chain runs A-B-D-G and A-B-E, longest span is G-D-B-E-? etc.
        DeskNode a = new DeskNode("Head");
        DeskNode b = new DeskNode("Regional");
        DeskNode c = new DeskNode("Audit");
        DeskNode d = new DeskNode("Zone");
        DeskNode e = new DeskNode("Branch");
        DeskNode g = new DeskNode("Terminal");

        a.setLeft(b); a.setRight(c);
        b.setLeft(d); b.setRight(e);
        d.setLeft(g);

        TreeDiameterService service = new TreeDiameterService();
        log.info("NBI longest escalation chain (nodes): "
                + service.longestEscalationChain(a));
    }
}
